class AcaoLink(SoftDeleteMixin):
    id=models.BigAutoField(primary_key=True,db_column='government_link_id'); uuid=models.UUIDField(default=uuid.uuid4,unique=True,editable=False,db_column='government_link_uuid'); acao=models.ForeignKey(AcaoPublica,on_delete=models.CASCADE,related_name='links',db_column='government_link_fk_acao'); titulo=models.CharField(max_length=180,db_column='government_link_titulo'); url=models.URLField(max_length=500,db_column='government_link_url'); tipo=models.CharField(max_length=30,blank=True,db_column='government_link_tipo'); ordem=models.PositiveIntegerField(default=0,db_column='government_link_ordem'); ativo=models.BooleanField(default=True,db_column='government_link_ativo'); criado_em=models.DateTimeField(auto_now_add=True,db_column='government_link_criado_em'); atualizado_em=models.DateTimeField(auto_now=True,db_column='government_link_atualizado_em'); excluido_em=models.DateTimeField(null=True,blank=True,db_column='government_link_excluido_em')
